-- ============================================================================
-- HoloLink — pełna migracja giełdy CDEX z JSON do SQL
-- Źródło: datapad_dane (gielda, gielda_notowania, gielda_portfele, katalog)
-- Zakres: 6 giełd, 41 instrumentów z JSON + 12 nowych notowań na Kuat,
--         historia kursów, ustawienia, portfel i transakcje gracza.
-- Model:  towary = globalny katalog (cena_bazowa = cena odniesienia)
--         instrumenty = towar x giełda (cena lokalna, jednostka, kategoria)
--         kursy_dzienne = historia; transakcje/portfele_gieldowe = gracze.
-- Konwencja symboli: symbol bez sufiksu = pierwsza giełda towaru; kolejne
--         notowania dostają sufiks, np. TIBP.KUA.
-- Uruchomić raz, w całości, na kopii bazy. Nie testowano na żywym MySQL.
-- ============================================================================
-- 1. Schemat (każdy krok sprawdza stan bazy, więc skrypt można uruchomić ponownie) --
-- Uwaga: ALTER TABLE w MySQL zatwierdza się natychmiast, transakcja go nie cofnie.
DROP PROCEDURE IF EXISTS `p_gielda_schemat`;
DELIMITER $$
CREATE PROCEDURE `p_gielda_schemat`()
BEGIN
  DECLARE ix VARCHAR(64);

  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='gielde' AND COLUMN_NAME='kod') THEN
    ALTER TABLE `gielde` ADD COLUMN `kod` VARCHAR(8) NOT NULL DEFAULT '' AFTER `id`;
  END IF;

  -- indeks pod klucz obcy towar_id musi istnieć, zanim zdejmiemy unikalność
  IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND INDEX_NAME='idx_instrumenty_towar') THEN
    ALTER TABLE `instrumenty` ADD KEY `idx_instrumenty_towar` (`towar_id`);
  END IF;

  -- unikalny indeks na samym towar_id, pod dowolną nazwą
  SELECT INDEX_NAME INTO ix FROM information_schema.STATISTICS
   WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND NON_UNIQUE=0 AND INDEX_NAME<>'PRIMARY'
   GROUP BY INDEX_NAME HAVING COUNT(*)=1 AND MAX(COLUMN_NAME)='towar_id' LIMIT 1;
  IF ix IS NOT NULL THEN
    SET @q := CONCAT('ALTER TABLE `instrumenty` DROP INDEX `', ix, '`');
    PREPARE st FROM @q; EXECUTE st; DEALLOCATE PREPARE st;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND INDEX_NAME='uq_instrumenty_gielda_towar') THEN
    ALTER TABLE `instrumenty` ADD UNIQUE KEY `uq_instrumenty_gielda_towar` (`gielda_id`,`towar_id`);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND COLUMN_NAME='kategoria') THEN
    ALTER TABLE `instrumenty` ADD COLUMN `kategoria` VARCHAR(40) NOT NULL DEFAULT '' AFTER `rodzaj`;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND COLUMN_NAME='jednostka') THEN
    ALTER TABLE `instrumenty` ADD COLUMN `jednostka` VARCHAR(30) NOT NULL DEFAULT 'szt' AFTER `kategoria`;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='instrumenty' AND COLUMN_NAME='pochodzenie') THEN
    ALTER TABLE `instrumenty` ADD COLUMN `pochodzenie` VARCHAR(80) NULL AFTER `jednostka`;
  END IF;

  ALTER TABLE `instrumenty`         MODIFY `cena_bazowa` DECIMAL(18,4) UNSIGNED NOT NULL;
  ALTER TABLE `kursy_dzienne`       MODIFY `kurs`        DECIMAL(18,4) UNSIGNED NOT NULL;
  ALTER TABLE `transakcje_gieldowe` MODIFY `kurs`        DECIMAL(18,4) UNSIGNED NOT NULL;

  IF NOT EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='gosp_towary' AND COLUMN_NAME='towar_id') THEN
    ALTER TABLE `gosp_towary` ADD COLUMN `towar_id` BIGINT UNSIGNED NULL AFTER `kod`;
    ALTER TABLE `gosp_towary` ADD UNIQUE KEY `uq_gosp_towary_towar` (`towar_id`);
    ALTER TABLE `gosp_towary` ADD CONSTRAINT `gosp_towary_ibfk_1` FOREIGN KEY (`towar_id`) REFERENCES `towary` (`id`);
  END IF;
END$$
DELIMITER ;
CALL `p_gielda_schemat`();
DROP PROCEDURE `p_gielda_schemat`;

START TRANSACTION;

-- 1b. Sprzątanie po wcześniejszym skrypcie tylko dla Kuat (kuat_gielda.sql) ------
-- Usuwa notowania giełdy Kuat i towary, które tamten skrypt dodał pod innymi nazwami.
-- Rekord giełdy Kuat zostaje i jest ponownie użyty. Przy pustej bazie nic nie robi.
DELETE k FROM `kursy_dzienne` k JOIN `instrumenty` i ON i.id=k.instrument_id JOIN `gielde` g ON g.id=i.gielda_id WHERE g.nazwa='Giełda Stoczniowa Kuat';
DELETE i FROM `instrumenty` i JOIN `gielde` g ON g.id=i.gielda_id WHERE g.nazwa='Giełda Stoczniowa Kuat';
UPDATE `gosp_towary` SET `towar_id`=NULL WHERE `towar_id` IN (SELECT id FROM `towary` WHERE `nazwa` IN ('Metale rzadkie (doonium, kammris, dolowit)','Durastal (blachy, profile)','Gaz tibanna','Żywność'));
DELETE FROM `towary_kategorie` WHERE `towar_id` IN (SELECT id FROM `towary` WHERE `nazwa` IN ('Metale rzadkie (doonium, kammris, dolowit)','Durastal (blachy, profile)','Gaz tibanna','Żywność'));
DELETE FROM `towary` WHERE `nazwa` IN ('Metale rzadkie (doonium, kammris, dolowit)','Durastal (blachy, profile)','Gaz tibanna','Żywność')
  AND NOT EXISTS (SELECT 1 FROM `instrumenty` x WHERE x.towar_id=`towary`.id);

