DROP PROCEDURE IF EXISTS `p_gielda_kod`;
DELIMITER $$
CREATE PROCEDURE `p_gielda_kod`()
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='gielde' AND INDEX_NAME='uq_gielde_kod') THEN
    ALTER TABLE `gielde` ADD UNIQUE KEY `uq_gielde_kod` (`kod`);
  END IF;
END$$
DELIMITER ;
CALL `p_gielda_kod`();
DROP PROCEDURE `p_gielda_kod`;
START TRANSACTION;

