INSERT INTO `kursy_dzienne` (`instrument_id`,`data`,`kurs`)
SELECT i.id,'2026-11-22',i.cena_bazowa FROM `instrumenty` i WHERE i.symbol IN ('FEO','WEG','LOM','KAR','MEL','ZER','NEU','PRE','ELK','ZYW','LUX','TIBP.KUA') ON DUPLICATE KEY UPDATE `kurs`=VALUES(`kurs`);

-- 10. Portfel i transakcje gracza ---------------------------------------------
-- UWAGA: tabele użytkowników, postaci i banku są jeszcze w JSON. Tworzę minimalny
-- podmiot postaci (Dave Stingert, login ISB-2137), który migracja użytkowników
-- powinna zastąpić. Księgowanie (ksiegowanie_id) zostaje NULL do migracji banku.
INSERT INTO `podmioty` (`typ`,`nazwa`,`status`) SELECT 'postac','Dave Stingert','aktywny' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `podmioty` WHERE `typ`='postac' AND `nazwa`='Dave Stingert');
INSERT INTO `postacie` (`podmiot_id`,`typ`,`frakcja_id`,`oddzial`,`ranga`,`poziom_uprawnien`)
SELECT p.id,'postac',(SELECT podmiot_id FROM `frakcje` WHERE kod='IMP'),'ISB','Kapitan',6 FROM `podmioty` p WHERE p.typ='postac' AND p.nazwa='Dave Stingert' AND NOT EXISTS (SELECT 1 FROM `postacie` x WHERE x.podmiot_id=p.id);
INSERT INTO `portfele_gieldowe` (`podmiot_id`,`instrument_id`,`ilosc`,`koszt_laczny`)
SELECT p.id,i.id,100,6819 FROM `podmioty` p, `instrumenty` i WHERE p.typ='postac' AND p.nazwa='Dave Stingert' AND i.symbol='OGN' ON DUPLICATE KEY UPDATE `ilosc`=VALUES(`ilosc`),`koszt_laczny`=VALUES(`koszt_laczny`);
INSERT INTO `transakcje_gieldowe` (`podmiot_id`,`instrument_id`,`strona`,`ilosc`,`kurs`,`prowizja`,`ksiegowanie_id`,`czas_utc`)
SELECT p.id,i.id,'kupno',100,67.85,34,NULL,'2026-11-13 19:49:47' FROM `podmioty` p, `instrumenty` i WHERE p.typ='postac' AND p.nazwa='Dave Stingert' AND i.symbol='OGN' AND NOT EXISTS (SELECT 1 FROM `transakcje_gieldowe` x WHERE x.podmiot_id=p.id AND x.instrument_id=i.id AND x.czas_utc='2026-11-13 19:49:47');

-- 11. Widoki dla API (zastępują obliczenia z JSON) ----------------------------
-- Zwraca instrument z ostatnim i poprzednim kursem; serię do wykresu pobiera
-- zapytanie po kursy_dzienne (instrument_id, data).
CREATE OR REPLACE VIEW `v_gielda_instrumenty` AS
SELECT i.id AS instrument_id, i.symbol, i.nazwa, i.rodzaj, i.kategoria, i.jednostka, i.pochodzenie,
       ge.kod AS gielda, i.notowany,
       k1.data AS dzien, k1.kurs AS kurs,
       (SELECT k2.kurs FROM `kursy_dzienne` k2 WHERE k2.instrument_id=i.id AND k2.data<k1.data ORDER BY k2.data DESC LIMIT 1) AS poprzedni
FROM `instrumenty` i
JOIN `gielde` ge ON ge.id=i.gielda_id
JOIN `kursy_dzienne` k1 ON k1.instrument_id=i.id AND k1.data=(SELECT MAX(x.data) FROM `kursy_dzienne` x WHERE x.instrument_id=i.id);

-- Wartość dostaw na Kuat po bieżących kursach giełdy Kuat.
CREATE OR REPLACE VIEW `v_kuat_dostawy_wartosc` AS
SELECT l.id AS linia_id, o.nazwa AS obiekt, o.rodzaj AS rodzaj_obiektu, l.towar AS kod_towaru, l.producent,
       l.t_doba, v.jednostka, tw.masa_t_na_jednostke,
       v.kurs AS kurs_kuat, ROUND(l.t_doba/tw.masa_t_na_jednostke*v.kurs,2) AS wartosc_doba
FROM `gosp_linie` l
JOIN `gosp_obiekty` o ON o.id=l.obiekt_id AND o.planeta='Kuat'
JOIN `gosp_towary` gt ON gt.kod=l.towar
JOIN `towary` tw ON tw.id=gt.towar_id
JOIN `instrumenty` i ON i.towar_id=gt.towar_id
JOIN `v_gielda_instrumenty` v ON v.instrument_id=i.id AND v.gielda='kua';

COMMIT;
